solution:
#include <vector>

void clip_returns(std::vector<double>& rets, double cap, int& clipped) {
    clipped = 0;
    for (double& r : rets) {
        if (r > cap) { r = cap; ++clipped; }
        else if (r < -cap) { r = -cap; ++clipped; }
    }
}

